<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, type Writer, type ReaderKey } from '../api/client'
const writers=ref<Writer[]>([]);const selected=ref<Writer|null>(null);const readerKeys=ref<ReaderKey[]>([]);const nickname=ref('');const readerNickname=ref('');const note=ref('');const issuedKey=ref('');const error=ref('');
async function refresh(){writers.value=(await api.writers()).items} async function select(writer:Writer){selected.value=writer;readerKeys.value=(await api.readerKeys(writer.life_id)).items} async function createWriter(){try{const result=await api.createWriter(nickname.value);issuedKey.value=`书写者 ${result.writer.nickname} 的主密钥：\n${result.master_key}`;nickname.value='';await refresh()}catch(e){error.value=e instanceof Error?e.message:'创建失败'}} async function createReader(){if(!selected.value)return;try{const result=await api.createReaderKey(selected.value.life_id,{nickname:readerNickname.value,note:note.value});issuedKey.value=`阅读者 ${result.reader_key.nickname} 的密钥：\n${result.key}`;readerNickname.value='';note.value='';await select(selected.value)}catch(e){error.value=e instanceof Error?e.message:'创建失败'}} async function revoke(id:string){if(!confirm('确认作废此阅读密钥？已有会话会立即失效。'))return;await api.revokeReaderKey(id);if(selected.value)await select(selected.value)} onMounted(refresh)
</script>
<template><main class="admin"><header><div><h1>人生空间管理</h1></div></header><p v-if="error" class="error">{{error}}</p><section v-if="issuedKey" class="key-output"><strong>请立即保存：</strong><pre>{{issuedKey}}</pre></section><section class="admin-grid"><aside class="panel"><h2>创建书写者</h2><form @submit.prevent="createWriter"><input v-model.trim="nickname" placeholder="书写者昵称" required/><button class="primary">创建并生成主密钥</button></form><hr/><h2>书写者列表</h2><button v-for="writer in writers" :key="writer.id" class="writer" :class="{selected:selected?.id===writer.id}" @click="select(writer)"><b>{{writer.nickname}}</b><small>{{writer.status}} · {{writer.life_id}}</small></button></aside><section class="panel"><template v-if="selected"><h2>{{selected.nickname}} 的阅读密钥</h2><form class="reader-form" @submit.prevent="createReader"><input v-model.trim="readerNickname" placeholder="阅读者昵称" required/><input v-model.trim="note" placeholder="备注（可选）"/><button class="primary">生成阅读密钥</button></form><div v-if="readerKeys.length===0" class="empty">尚未创建阅读密钥。</div><article v-for="key in readerKeys" :key="key.id" class="reader"><div><b>{{key.nickname}}</b><small>锚点：{{key.anchor_local_date}} · {{key.note||'无备注'}}</small></div><span v-if="key.revoked_at" class="revoked">已作废</span><button v-else @click="revoke(key.id)">作废</button></article></template><div v-else class="empty">从左侧选择一位书写者。</div></section></section></main></template>